import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../App';

const LANG_META = {
  en:{native:'English',flag:'🇬🇧'}, hi:{native:'हिंदी',flag:'🇮🇳'}, mr:{native:'मराठी',flag:'🌾'},
  pa:{native:'ਪੰਜਾਬੀ',flag:'🌻'}, te:{native:'తెలుగు',flag:'🌴'}, bn:{native:'বাংলা',flag:'🐯'},
  gu:{native:'ગુજરાતી',flag:'🦁'}, ta:{native:'தமிழ்',flag:'🌺'}, kn:{native:'ಕನ್ನಡ',flag:'🐘'},
  or:{native:'ଓଡ଼ିଆ',flag:'🌊'}, ur:{native:'اردو',flag:'🌙'},
};

const CROPS  = ['Wheat','Rice','Cotton','Sugarcane','Maize','Soybean','Tomato','Onion'];
const STATES = ['Maharashtra','Punjab','Uttar Pradesh','Madhya Pradesh','Rajasthan','Gujarat','Karnataka','Andhra Pradesh'];

/* ── Floating particle component ── */
function Particles() {
  const particles = Array.from({ length: 18 }, (_, i) => ({
    id: i,
    size:  Math.random() * 4 + 2,
    left:  Math.random() * 100,
    delay: Math.random() * 8,
    dur:   Math.random() * 6 + 7,
  }));
  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
      {particles.map(p => (
        <div key={p.id} className="particle" style={{
          width: p.size, height: p.size,
          left: `${p.left}%`,
          animationDuration: `${p.dur}s`,
          animationDelay: `${p.delay}s`,
        }}/>
      ))}
    </div>
  );
}

/* ── GPS Permission Popup ── */
function GPSPopup({ onAllow, onSkip }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center px-4"
      style={{ background: 'rgba(0,0,0,0.70)', backdropFilter: 'blur(6px)' }}>
      <div className="gps-popup p-8 max-w-sm w-full text-center animate-slide-up">
        <div className="text-6xl mb-4 animate-float">📍</div>
        <h3 className="font-display font-bold text-white text-xl mb-2">Enable GPS Location</h3>
        <p className="text-green-300 text-sm mb-1 font-medium">SmartSheti AI wants to access your location</p>
        <p className="text-gray-400 text-xs mb-7 leading-relaxed">
          We use your GPS to provide hyperlocal weather forecasts, soil data, and crop recommendations specific to your farm location.
        </p>
        <div className="space-y-3">
          <button onClick={onAllow}
            className="login-btn w-full py-3.5 text-base font-bold rounded-xl flex items-center justify-center gap-2">
            📍 Allow Location Access
          </button>
          <button onClick={onSkip}
            className="w-full py-3 text-sm font-medium rounded-xl transition-all"
            style={{ color: 'rgba(255,255,255,0.50)', background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.12)' }}>
            Skip for now
          </button>
        </div>
      </div>
    </div>
  );
}

/* ── Left info panel ── */
function InfoPanel() {
  const features = [
    { icon: '🌱', text: 'AI Crop Recommendations' },
    { icon: '🔬', text: 'Disease Detection (95% accuracy)' },
    { icon: '💰', text: 'Profit & Market Predictions' },
    { icon: '🌦️', text: 'Hyperlocal Weather Alerts' },
    { icon: '🤖', text: 'KisanGPT Voice Assistant' },
  ];
  return (
    <div className="hidden lg:flex flex-col justify-center px-12 py-16 max-w-lg">
      <div className="mb-10">
        <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full mb-6"
          style={{ background: 'rgba(74,222,128,0.15)', border: '1px solid rgba(74,222,128,0.30)' }}>
          <span className="w-2 h-2 rounded-full bg-green-400 animate-pulse"/>
          <span className="text-green-300 text-xs font-semibold tracking-wider uppercase">AI-Powered Platform</span>
        </div>
        <h1 className="font-display font-black text-5xl text-white leading-tight mb-4">
          Farm Smarter.<br/>
          <span style={{ background: 'linear-gradient(135deg,#4ade80,#22c55e,#86efac)', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent' }}>
            Earn Better.
          </span>
        </h1>
        <p className="text-gray-300 text-base leading-relaxed">
          India's most advanced AI farming platform — giving every farmer the power of data, intelligence, and technology.
        </p>
      </div>

      <div className="space-y-3 mb-10">
        {features.map((f, i) => (
          <div key={i} className="flex items-center gap-3 animate-fade-in" style={{ animationDelay: `${i * 0.1}s` }}>
            <div className="w-9 h-9 rounded-xl flex items-center justify-center text-lg flex-shrink-0"
              style={{ background: 'rgba(22,163,74,0.20)', border: '1px solid rgba(74,222,128,0.25)' }}>
              {f.icon}
            </div>
            <span className="text-gray-200 text-sm font-medium">{f.text}</span>
          </div>
        ))}
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-3 gap-4">
        {[
          { val: '2.4L+', label: 'Farmers' },
          { val: '95%',   label: 'Accuracy' },
          { val: '11',    label: 'Languages' },
        ].map(s => (
          <div key={s.label} className="text-center p-3 rounded-2xl"
            style={{ background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.10)' }}>
            <div className="font-display font-black text-2xl text-green-400">{s.val}</div>
            <div className="text-gray-400 text-xs mt-0.5">{s.label}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── Main component ── */
export default function AuthPage() {
  const [tab, setTab]           = useState('login');
  const [form, setForm]         = useState({ name:'', phone:'', password:'', state:'', crop:'', acres:'' });
  const [showPass, setShowPass] = useState(false);
  const [locating, setLocating] = useState(false);
  const [location, setLocation] = useState(null);
  const [loading, setLoading]   = useState(false);
  const [error, setError]       = useState('');
  const [showGPS, setShowGPS]   = useState(false);
  const [pendingUser, setPendingUser] = useState(null);
  const { setUser, lang }       = useAuth();
  const navigate                = useNavigate();
  const langMeta                = LANG_META[lang] || LANG_META.en;

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const detectGPS = () => {
    setLocating(true);
    navigator.geolocation?.getCurrentPosition(
      pos => { setLocation({ lat: pos.coords.latitude.toFixed(4), lng: pos.coords.longitude.toFixed(4) }); setLocating(false); },
      ()  => { setLocation({ lat: '18.5204', lng: '73.8567' }); setLocating(false); }
    );
  };

  const handleSubmit = (e) => {
    e.preventDefault(); setError('');
    if (!form.phone || !form.password) { setError('Please fill all required fields.'); return; }
    setLoading(true);
    setTimeout(() => {
      const user = { name: form.name || 'Farmer', phone: form.phone, state: form.state || 'India', crop: form.crop, acres: form.acres, gps: location };
      setLoading(false);
      setPendingUser(user);
      setShowGPS(true);
    }, 1000);
  };

  const handleGPSAllow = () => {
    navigator.geolocation?.getCurrentPosition(
      pos => {
        const gps = { lat: pos.coords.latitude.toFixed(4), lng: pos.coords.longitude.toFixed(4) };
        setUser({ ...pendingUser, gps });
        navigate('/dashboard');
      },
      () => { setUser(pendingUser); navigate('/dashboard'); }
    );
  };

  const handleGPSSkip = () => { setUser(pendingUser); navigate('/dashboard'); };

  /* Input style helper */
  const inp = "login-input px-4 py-3 text-sm";
  const sel = "login-input px-3 py-3 text-sm";

  return (
    <div className="auth-bg flex min-h-screen">
      <Particles />
      {showGPS && <GPSPopup onAllow={handleGPSAllow} onSkip={handleGPSSkip} />}

      {/* Left panel */}
      <div className="relative z-10 flex-1 flex items-center">
        <InfoPanel />
      </div>

      {/* Right — login card */}
      <div className="relative z-10 flex items-center justify-center w-full lg:w-auto px-4 py-10 lg:px-16">
        <div className="w-full max-w-md animate-slide-up">

          {/* Card */}
          <div className="login-glass p-8 relative overflow-hidden">
            {/* Scan line */}
            <div className="scan-line" />

            {/* Logo */}
            <div className="text-center mb-7">
              <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl mb-4 logo-glow"
                style={{ background: 'linear-gradient(135deg,#15803d,#22c55e)' }}>
                <span className="text-3xl">🌿</span>
              </div>
              <h2 className="font-display font-black text-2xl text-white mb-1">SmartSheti <span className="text-green-400">AI</span></h2>
              <p className="text-gray-400 text-xs">India's Smartest Farming Platform</p>

              {/* Language badge */}
              <div className="flex items-center justify-center gap-2 mt-3">
                <div className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold"
                  style={{ background: 'rgba(74,222,128,0.15)', border: '1px solid rgba(74,222,128,0.30)', color: '#4ade80' }}>
                  <span>{langMeta.flag}</span> {langMeta.native}
                </div>
                <button onClick={() => navigate('/select-language')}
                  className="text-xs font-medium underline underline-offset-2 transition-colors"
                  style={{ color: 'rgba(255,255,255,0.45)' }}
                  onMouseEnter={e => e.target.style.color='#4ade80'}
                  onMouseLeave={e => e.target.style.color='rgba(255,255,255,0.45)'}>
                  Change
                </button>
              </div>
            </div>

            {/* Tabs */}
            <div className="flex p-1 rounded-xl mb-6 gap-1"
              style={{ background: 'rgba(0,0,0,0.25)', border: '1px solid rgba(255,255,255,0.08)' }}>
              {['login','register'].map(t => (
                <button key={t} onClick={() => { setTab(t); setError(''); }}
                  className={`flex-1 py-2.5 text-sm font-semibold transition-all capitalize ${tab===t?'login-tab-active':'login-tab-inactive'}`}>
                  {t === 'login' ? '🔑 Login' : '🌱 Register'}
                </button>
              ))}
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="space-y-4">

              {tab === 'register' && (
                <div>
                  <label className="block text-xs font-semibold uppercase tracking-wider mb-1.5" style={{ color:'rgba(255,255,255,0.55)' }}>Full Name</label>
                  <input value={form.name} onChange={e=>set('name',e.target.value)}
                    placeholder="Ramesh Kumar" className={inp}/>
                </div>
              )}

              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider mb-1.5" style={{ color:'rgba(255,255,255,0.55)' }}>
                  📱 Phone Number *
                </label>
                <input value={form.phone} onChange={e=>set('phone',e.target.value)}
                  placeholder="+91 98765 43210" type="tel" className={inp}/>
              </div>

              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <label className="text-xs font-semibold uppercase tracking-wider" style={{ color:'rgba(255,255,255,0.55)' }}>
                    🔒 Password *
                  </label>
                  {tab === 'login' && (
                    <button type="button" className="text-xs transition-colors"
                      style={{ color:'rgba(74,222,128,0.80)' }}
                      onMouseEnter={e=>e.target.style.color='#4ade80'}
                      onMouseLeave={e=>e.target.style.color='rgba(74,222,128,0.80)'}>
                      Forgot password?
                    </button>
                  )}
                </div>
                <div className="relative">
                  <input value={form.password} onChange={e=>set('password',e.target.value)}
                    placeholder="••••••••" type={showPass?'text':'password'} className={inp}
                    style={{ paddingRight: '44px' }}/>
                  <button type="button" onClick={()=>setShowPass(s=>!s)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-base"
                    style={{ color:'rgba(255,255,255,0.40)' }}>
                    {showPass ? '🙈' : '👁️'}
                  </button>
                </div>
              </div>

              {tab === 'register' && (
                <>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs font-semibold uppercase tracking-wider mb-1.5" style={{ color:'rgba(255,255,255,0.55)' }}>State</label>
                      <select value={form.state} onChange={e=>set('state',e.target.value)} className={sel}>
                        <option value="">Select</option>
                        {STATES.map(s=><option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-semibold uppercase tracking-wider mb-1.5" style={{ color:'rgba(255,255,255,0.55)' }}>Main Crop</label>
                      <select value={form.crop} onChange={e=>set('crop',e.target.value)} className={sel}>
                        <option value="">Select</option>
                        {CROPS.map(c=><option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-semibold uppercase tracking-wider mb-1.5" style={{ color:'rgba(255,255,255,0.55)' }}>Farm Size (Acres)</label>
                    <input value={form.acres} onChange={e=>set('acres',e.target.value)}
                      placeholder="e.g. 5" type="number" className={inp}/>
                  </div>

                  <div>
                    <label className="block text-xs font-semibold uppercase tracking-wider mb-1.5" style={{ color:'rgba(255,255,255,0.55)' }}>GPS Location</label>
                    <button type="button" onClick={detectGPS}
                      className={`w-full py-3 text-sm font-semibold rounded-xl flex items-center justify-center gap-2 transition-all ${locating?'opacity-60':''}`}
                      style={{ background:'rgba(22,163,74,0.15)', border:'1.5px solid rgba(74,222,128,0.35)', color:'#4ade80' }}>
                      {locating
                        ? <><span className="animate-spin">⟳</span> Detecting...</>
                        : location
                          ? <>📍 {location.lat}, {location.lng}</>
                          : <>📍 Detect My Location</>
                      }
                    </button>
                  </div>
                </>
              )}

              {error && (
                <div className="px-4 py-2.5 rounded-xl text-sm text-center font-medium"
                  style={{ background:'rgba(239,68,68,0.15)', border:'1px solid rgba(239,68,68,0.35)', color:'#fca5a5' }}>
                  ⚠️ {error}
                </div>
              )}

              <button type="submit" disabled={loading}
                className="login-btn w-full py-4 text-base font-bold rounded-xl flex items-center justify-center gap-2 mt-1">
                {loading
                  ? <><span className="animate-spin text-xl">⟳</span> Processing...</>
                  : tab === 'login'
                    ? '🚀 Login to Dashboard'
                    : '🌱 Create My Farm Account'
                }
              </button>
            </form>

            {/* Divider */}
            <div className="flex items-center gap-3 my-5">
              <div className="flex-1 h-px" style={{ background:'rgba(255,255,255,0.12)' }}/>
              <span className="text-xs" style={{ color:'rgba(255,255,255,0.30)' }}>or</span>
              <div className="flex-1 h-px" style={{ background:'rgba(255,255,255,0.12)' }}/>
            </div>

            {/* Switch tab */}
            <p className="text-center text-xs" style={{ color:'rgba(255,255,255,0.45)' }}>
              {tab === 'login' ? "Don't have an account? " : 'Already registered? '}
              <button onClick={()=>{ setTab(tab==='login'?'register':'login'); setError(''); }}
                className="font-bold transition-colors"
                style={{ color:'#4ade80' }}
                onMouseEnter={e=>e.target.style.color='#86efac'}
                onMouseLeave={e=>e.target.style.color='#4ade80'}>
                {tab === 'login' ? 'Register Free →' : 'Login →'}
              </button>
            </p>
          </div>

          {/* Bottom note */}
          <p className="text-center mt-5 text-xs" style={{ color:'rgba(255,255,255,0.28)' }}>
            🔒 Secured · 🌿 Built for Indian Farmers · 🤖 Powered by AI
          </p>
        </div>
      </div>
    </div>
  );
}
